#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct TreeNode {
    int val;
    struct TreeNode* left;
    struct TreeNode* right;
} TreeNode;

typedef struct {
    TreeNode* node;
    int visited;
} StackEntry;

static TreeNode* newNode(int value) {
    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));
    if (!node) return NULL;
    node->val = value;
    node->left = NULL;
    node->right = NULL;
    return node;
}

static TreeNode* buildTree(const char* line) {
    const char* first = strchr(line, '[');
    const char* second = first ? strchr(first + 1, '[') : NULL;
    const char* last = strrchr(line, ']');

    if (!first || !second || !last || last <= second) return NULL;

    const char* innerLast = last - 1;
    while (innerLast > second &&
           (*innerLast == ' ' || *innerLast == '\t' ||
            *innerLast == '\n' || *innerLast == '\r')) {
        --innerLast;
    }

    if (innerLast <= second) return NULL;

    size_t len = (size_t)(innerLast - second - 1);
    char* body = (char*)malloc(len + 1);
    if (!body) return NULL;

    memcpy(body, second + 1, len);
    body[len] = '\0';

    size_t start = 0;
    while (body[start] == ' ' || body[start] == '\t') ++start;

    if (body[start] == '\0' || strcmp(body + start, "null") == 0) {
        free(body);
        return NULL;
    }

    size_t cap = 1024, count = 0;
    int* values = (int*)malloc(cap * sizeof(int));
    if (!values) {
        free(body);
        return NULL;
    }

    char* tok = strtok(body, ",");
    while (tok) {
        if (count == cap) {
            cap *= 2;
            values = (int*)realloc(values, cap * sizeof(int));
        }

        while (*tok == ' ' || *tok == '\t') ++tok;

        if (strncmp(tok, "null", 4) == 0)
            values[count++] = 0x7fffffff;
        else
            values[count++] = atoi(tok);

        tok = strtok(NULL, ",");
    }

    TreeNode** nodes = (TreeNode**)calloc(count, sizeof(TreeNode*));
    if (!nodes) {
        free(values);
        free(body);
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        if (values[i] != 0x7fffffff)
            nodes[i] = newNode(values[i]);
    }

    TreeNode* root = nodes[0];

    TreeNode** queue = (TreeNode**)malloc(count * sizeof(TreeNode*));
    size_t head = 0, tail = 0, i = 1;

    if (root) queue[tail++] = root;

    while (head < tail && i < count) {
        TreeNode* cur = queue[head++];

        if (i < count) {
            cur->left = nodes[i];
            if (nodes[i]) queue[tail++] = nodes[i];
            ++i;
        }

        if (i < count) {
            cur->right = nodes[i];
            if (nodes[i]) queue[tail++] = nodes[i];
            ++i;
        }
    }

    free(queue);
    free(nodes);
    free(values);
    free(body);

    return root;
}

int findTilt(TreeNode* root) {
    if (!root) return 0;

    /*
     * Explicit post-order traversal.
     *
     * Each stack entry stores:
     *   visited = 0 -> first visit
     *   visited = 1 -> both children are already processed
     *
     * A parallel array stores completed subtree sums. Because a completed
     * child is always the most recently completed node before its parent,
     * child sums can be carried back through a second stack of frames.
     */
    size_t cap = 1024;
    size_t top = 0;

    long long total = 0;

    /*
     * Use a frame containing the node plus the sums of its completed
     * children. This gives O(n) time and O(h) auxiliary space.
     */
    typedef struct {
        TreeNode* node;
        long long leftSum;
        long long rightSum;
        int state;
    } Frame;

    Frame* frames = (Frame*)malloc(cap * sizeof(Frame));
    if (!frames) {
        return 0;
    }

    top = 0;
    frames[top++] = (Frame){root, 0, 0, 0};

    /*
     * The stack itself is used as an explicit call stack. When a child
     * finishes, its subtree sum is returned to the parent frame.
     */
    while (top > 0) {
        Frame* f = &frames[top - 1];

        if (f->state == 0) {
            f->state = 1;

            if (f->node->left) {
                if (top == cap) {
                    size_t newCap = cap * 2;
                    Frame* newFrames = (Frame*)realloc(
                        frames, newCap * sizeof(Frame)
                    );
                    if (!newFrames) {
                        free(frames);
                        return 0;
                    }
                    frames = newFrames;
                    cap = newCap;
                    f = &frames[top - 1];
                }
                frames[top++] = (Frame){f->node->left, 0, 0, 0};
            }
        } else if (f->state == 1) {
            f->state = 2;

            if (f->node->right) {
                if (top == cap) {
                    size_t newCap = cap * 2;
                    Frame* newFrames = (Frame*)realloc(
                        frames, newCap * sizeof(Frame)
                    );
                    if (!newFrames) {
                        free(frames);
                        return 0;
                    }
                    frames = newFrames;
                    cap = newCap;
                    f = &frames[top - 1];
                }
                frames[top++] = (Frame){f->node->right, 0, 0, 0};
            }
        } else {
            long long subtreeSum =
                f->leftSum + f->rightSum + f->node->val;

            long long diff = f->leftSum - f->rightSum;
            if (diff < 0) diff = -diff;

            total += diff;

            --top;

            if (top > 0) {
                Frame* parent = &frames[top - 1];

                if (parent->state == 1)
                    parent->leftSum = subtreeSum;
                else
                    parent->rightSum = subtreeSum;
            }
        }
    }

    free(frames);
    return (int)total;
}

static void freeTree(TreeNode* root) {
    if (!root) return;

    size_t cap = 1024;
    size_t top = 0;
    TreeNode** stack = (TreeNode**)malloc(cap * sizeof(TreeNode*));
    if (!stack) {
        return;
    }

    stack[top++] = root;

    while (top > 0) {
        TreeNode* node = stack[--top];

        if (node->left) {
            if (top == cap) {
                size_t newCap = cap * 2;
                TreeNode** newStack =
                    (TreeNode**)realloc(stack, newCap * sizeof(TreeNode*));
                if (!newStack) {
                    free(stack);
                    return;
                }
                stack = newStack;
                cap = newCap;
            }
            stack[top++] = node->left;
        }

        if (node->right) {
            if (top == cap) {
                size_t newCap = cap * 2;
                TreeNode** newStack =
                    (TreeNode**)realloc(stack, newCap * sizeof(TreeNode*));
                if (!newStack) {
                    free(stack);
                    return;
                }
                stack = newStack;
                cap = newCap;
            }
            stack[top++] = node->right;
        }

        free(node);
    }

    free(stack);
}

