class Solution {
public:
    int findTilt(TreeNode* root) {
        if (!root) return 0;
        long long total = 0;
        unordered_map<TreeNode*, long long> sums;
        vector<pair<TreeNode*, bool>> st;
        st.push_back({root, false});

        while (!st.empty()) {
            auto [node, visited] = st.back();
            st.pop_back();
            if (!node) continue;
            if (!visited) {
                st.push_back({node, true});
                st.push_back({node->right, false});
                st.push_back({node->left, false});
            } else {
                long long leftSum = node->left ? sums[node->left] : 0LL;
                long long rightSum = node->right ? sums[node->right] : 0LL;
                total += llabs(leftSum - rightSum);
                sums[node] = leftSum + rightSum + node->val;
            }
        }
        return static_cast<int>(total);
    }
};

