class Solution {
    public int findTilt(TreeNode root) {
        if (root == null) return 0;
        long total = 0;
        IdentityHashMap<TreeNode, Long> sums = new IdentityHashMap<>();
        ArrayDeque<TreeNode> nodes = new ArrayDeque<>();
        ArrayDeque<Boolean> visited = new ArrayDeque<>();
        nodes.push(root);
        visited.push(false);

        while (!nodes.isEmpty()) {
            TreeNode node = nodes.pop();
            boolean done = visited.pop();
            if (!done) {
                nodes.push(node);
                visited.push(true);
                if (node.right != null) {
                    nodes.push(node.right);
                    visited.push(false);
                }
                if (node.left != null) {
                    nodes.push(node.left);
                    visited.push(false);
                }
            } else {
                long leftSum = node.left == null ? 0L : sums.get(node.left);
                long rightSum = node.right == null ? 0L : sums.get(node.right);
                total += Math.abs(leftSum - rightSum);
                sums.put(node, leftSum + rightSum + node.val);
            }
        }
        return (int) total;
    }
}

